package net.newpipe.app.viewmodel.settings

import androidx.lifecycle.ViewModel
import com.russhwolf.settings.Settings
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import net.newpipe.app.platform.AppearanceActions
import net.newpipe.app.preferences.AppearancePreferences
import org.koin.core.annotation.KoinViewModel

@KoinViewModel
class AppearanceSettingsViewModel(
    private val settings: Settings,
    private val appearanceActions: AppearanceActions,
) : ViewModel() {

    val theme: StateFlow<String>
        field = MutableStateFlow(
            settings.getString(AppearancePreferences.KEY_THEME, AppearancePreferences.DEFAULT_THEME)
        )

    val nightTheme: StateFlow<String>
        field = MutableStateFlow(
            settings.getString(
                AppearancePreferences.KEY_NIGHT_THEME,
                AppearancePreferences.DEFAULT_NIGHT_THEME
            )
        )

    val holdToAppend: StateFlow<Boolean>
        field = MutableStateFlow(
            settings.getBoolean(
                AppearancePreferences.KEY_HOLD_TO_APPEND,
                AppearancePreferences.DEFAULT_HOLD_TO_APPEND
            )
        )

    val tabletMode: StateFlow<String>
        field = MutableStateFlow(
            settings.getString(
                AppearancePreferences.KEY_TABLET_MODE,
                AppearancePreferences.DEFAULT_TABLET_MODE
            )
        )

    val listViewMode: StateFlow<String>
        field = MutableStateFlow(
            settings.getString(
                AppearancePreferences.KEY_LIST_VIEW_MODE,
                AppearancePreferences.DEFAULT_LIST_VIEW_MODE
            )
        )

    val mainTabsPosition: StateFlow<Boolean>
        field = MutableStateFlow(
            settings.getBoolean(
                AppearancePreferences.KEY_MAIN_TABS_POSITION,
                AppearancePreferences.DEFAULT_MAIN_TABS_POSITION
            )
        )

    fun setTheme(value: String) {
        settings.putString(AppearancePreferences.KEY_THEME, value)
        theme.value = value
        appearanceActions.applyThemeChange(value)
    }

    fun setNightTheme(value: String) {
        settings.putString(AppearancePreferences.KEY_NIGHT_THEME, value)
        nightTheme.value = value
        appearanceActions.applyThemeChange(theme.value)
    }

    fun setHoldToAppend(value: Boolean) {
        settings.putBoolean(AppearancePreferences.KEY_HOLD_TO_APPEND, value)
        holdToAppend.value = value
    }

    fun setTabletMode(value: String) {
        settings.putString(AppearancePreferences.KEY_TABLET_MODE, value)
        tabletMode.value = value
    }

    fun setListViewMode(value: String) {
        settings.putString(AppearancePreferences.KEY_LIST_VIEW_MODE, value)
        listViewMode.value = value
    }

    fun setMainTabsPosition(value: Boolean) {
        settings.putBoolean(AppearancePreferences.KEY_MAIN_TABS_POSITION, value)
        mainTabsPosition.value = value
    }
}

package org.schabi.newpipe.info_list

import android.util.Log
import com.xwray.groupie.GroupieAdapter
import kotlin.math.max
import org.schabi.newpipe.extractor.stream.StreamInfo

/**
 * Custom RecyclerView.Adapter/GroupieAdapter for [StreamSegmentItem] for handling selection state.
 */
class StreamSegmentAdapter(
    private val listener: StreamSegmentListener
) : GroupieAdapter() {

    var currentIndex: Int = 0
        private set

    /**
     * Returns `true` if the provided [StreamInfo] contains segments, `false` otherwise.
     */
    fun setItems(info: StreamInfo): Boolean {
        if (info.streamSegments.isNotEmpty()) {
            clear()
            addAll(info.streamSegments.map { StreamSegmentItem(it, listener) })
            return true
        }
        return false
    }

    fun selectSegment(segment: StreamSegmentItem) {
        unSelectCurrentSegment()
        currentIndex = max(0, getAdapterPosition(segment))
        segment.isSelected = true
        segment.notifyChanged(StreamSegmentItem.PAYLOAD_SELECT)
    }

    fun selectSegmentAt(position: Int) {
        try {
            selectSegment(getGroupAtAdapterPosition(position) as StreamSegmentItem)
        } catch (e: IndexOutOfBoundsException) {
            // Just to make sure that getGroupAtAdapterPosition doesn't close the app
            // Shouldn't happen since setItems is always called before select-methods but just in case
            currentIndex = 0
            Log.e("StreamSegmentAdapter", "selectSegmentAt: ${e.message}")
        }
    }

    private fun unSelectCurrentSegment() {
        try {
            val segmentItem = getGroupAtAdapterPosition(currentIndex) as StreamSegmentItem
            currentIndex = 0
            segmentItem.isSelected = false
            segmentItem.notifyChanged(StreamSegmentItem.PAYLOAD_SELECT)
        } catch (e: IndexOutOfBoundsException) {
            // Just to make sure that getGroupAtAdapterPosition doesn't close the app
            // Shouldn't happen since setItems is always called before select-methods but just in case
            currentIndex = 0
            Log.e("StreamSegmentAdapter", "unSelectCurrentSegment: ${e.message}")
        }
    }

    interface StreamSegmentListener {
        fun onItemClick(item: StreamSegmentItem, seconds: Int)
        fun onItemLongClick(item: StreamSegmentItem, seconds: Int)
    }
}

